  let next;

  next = readMtpStringAt(bytes, offset);
  result.filename = next.text;
  offset = next.offset;

  next = readMtpStringAt(bytes, offset);
  result.dateCreated = next.text;
  offset = next.offset;

  next = readMtpStringAt(bytes, offset);
  result.dateModified = next.text;
  offset = next.offset;

  next = readMtpStringAt(bytes, offset);
  result.keywords = next.text;

